const order=$('Fetch Rental Reservation').first().json, stock=$('Fetch Kit Stock').first().json;
const cfg=$('Normalise Kit Event').first().json;
let errors=[]; let requirements=[];
if(order.error || !order.id || order.id!==cfg.recordId) errors.push('Reservation not found');
if(stock.error || !Array.isArray(stock.records) || stock.offset) errors.push('Stock read missing or paginated');
try {requirements=JSON.parse(order.fields?.RequirementsJson||'null');if(!Array.isArray(requirements)||!requirements.length||requirements.length>50) throw Error();}catch{errors.push('RequirementsJson must contain 1–50 lines'); requirements=[];}
const bySku=new Map();
for(const r of stock.records||[]){const s=r.fields||{};if(!s.Sku||bySku.has(s.Sku)||!Number.isInteger(s.FreeQty)||s.FreeQty<0) errors.push('Invalid/duplicate stock SKU');else bySku.set(s.Sku,{...s,remaining:s.FreeQty});}
const lines=[];
for(const q of requirements){
 if(!q.sku||!Number.isInteger(q.qty)||q.qty<=0||!Array.isArray(q.approvedSubstitutes)){errors.push('Invalid kit line');continue;}
 const s=bySku.get(q.sku); let remaining=q.qty;const allocations=[];
 if(s){const take=Math.min(s.remaining,remaining);if(take){allocations.push({sku:q.sku,qty:take,substitute:false});s.remaining-=take;remaining-=take;}}
 for(const sku of q.approvedSubstitutes){if(!remaining) break; const t=bySku.get(sku); if(!t || t.CompatibilityGroup!==q.compatibilityGroup) continue; const take=Math.min(remaining,t.remaining);if(take){allocations.push({sku,qty:take,substitute:true});t.remaining-=take;remaining-=take;}}
 lines.push({sku:q.sku,required:q.qty,allocations,shortage:remaining});
}
const dispatch=Date.parse(order.fields?.DispatchAt||'');
if(!Number.isFinite(dispatch)) errors.push('DispatchAt missing');
const hoursToDispatch=(dispatch-Date.now())/3600000;
const shortage=lines.reduce((s,x)=>s+x.shortage,0), substitutions=lines.some(x=>x.allocations.some(a=>a.substitute));
const route=shortage?(hoursToDispatch>=cfg.crossHireLeadHours?'crosshire':'blocked'):(substitutions?'substitute':'ready');
return [{json:{valid:!errors.length,errors,recordId:order.id,eventId:cfg.eventId,route,lines,shortage,hoursToDispatch,recipient:cfg.recipient,subject:`[Kit review] ${order.fields?.JobName||order.id}: ${route}`,reportText:JSON.stringify({route,lines,hoursToDispatch},null,2),notes:String(order.fields?.TechnicianNotes||'').slice(0,2000)}}];
